import { z } from "zod";
import { AMOUNT_BUCKETS, CARD_SCHEMES, COUNTRIES, CURRENCIES, PAYMENT_METHODS } from "../domain/types.js";

/**
 * Section 5.4 transaction stream distribution. Amounts are generated by first choosing a
 * bucket by weight, then sampling a value within that bucket's bounds from a truncated
 * lognormal (median `medianEUR`, shape `sigma`). This guarantees the configured bucket
 * proportions exactly (by construction) rather than approximately, which a single untruncated
 * lognormal cannot do for arbitrary bucket boundaries. See docs/assumptions.md.
 */
export const StreamConfigSchema = z.object({
  amount: z.object({
    medianEUR: z.number().positive(),
    sigma: z.number().positive(),
    smallMax: z.number().positive(),
    largeMin: z.number().positive(),
    bucketWeights: z.object({
      small: z.number().nonnegative(),
      medium: z.number().nonnegative(),
      large: z.number().nonnegative(),
    }),
  }),
  countryCurrency: z
    .array(
      z.object({
        country: z.enum(COUNTRIES),
        currency: z.enum(CURRENCIES),
        weight: z.number().nonnegative(),
      })
    )
    .min(1),
  paymentMethod: z.object({
    card: z.number().nonnegative(),
    paypal: z.number().nonnegative(),
    sepa_debit: z.number().nonnegative(),
  }),
  cardScheme: z.object({
    visa: z.number().nonnegative(),
    mastercard: z.number().nonnegative(),
    amex: z.number().nonnegative(),
  }),
  device: z.object({
    mobile: z.number().nonnegative(),
    desktop: z.number().nonnegative(),
  }),
  customerType: z.object({
    returning: z.number().nonnegative(),
    new: z.number().nonnegative(),
  }),
  threeDsEligibleRateForCard: z.number().min(0).max(1),
});
export type StreamConfig = z.infer<typeof StreamConfigSchema>;

export const AMOUNT_BUCKET_NAMES = AMOUNT_BUCKETS;
export const CARD_SCHEME_NAMES = CARD_SCHEMES;
export const PAYMENT_METHOD_NAMES = PAYMENT_METHODS;
